const items = $input.all();

const dadosOriginais = items[0] ? items[0].json : null;
const respostaAgent = items[1] ? items[1].json : null;

if (!dadosOriginais || !respostaAgent) {
  return [];
}

const phone = dadosOriginais.phone;
const message = respostaAgent.message || respostaAgent.output;
const config = dadosOriginais._config || {};

if (!phone || !message) {
  throw new Error('Faltam dados: phone=' + phone + ', message=' + (message ? 'OK' : 'VAZIO'));
}

if (!config.zapi_url || !config.client_token) {
  throw new Error('Configuracao incompleta no _config');
}

let zapi_url = config.zapi_url;
if (!zapi_url.endsWith('/send-text')) {
  zapi_url = zapi_url.replace(/\/(send-text|send-button-list|send-image).*$/, '') + '/send-text';
}

const fingerprint = 'agent_' + Math.random().toString(36).slice(2) + Date.now().toString(36);

return [{
  json: {
    ...dadosOriginais,
    phone: phone,
    message: message,
    output: respostaAgent.output,
    _zapi_url: zapi_url,
    _zapi_token: config.client_token,
    _agent_fingerprint: fingerprint
  }
}];

// ============================================
// 07 – EXTRAIR RESPOSTA DO AGENT (PRODUÇÃO)
// Função: padronizar saída do LLM
// NÃO decide estado
// NÃO remove bloco [ESTADO_NOVO]
// ============================================

const data = $json;

// Resposta bruta do LLM (sempre manter íntegra)
const respostaBruta =
  data.output ||
  data.message ||
  "";

// Fallback seguro
const resposta =
  respostaBruta.trim() ||
  "Desculpe, não consegui processar sua mensagem agora.";

// Output padronizado
return [{
  json: {
    ...data,

    // 🔹 resposta ainda COMPLETA (com estado)
    output: resposta,
    message: resposta,

    // 🔹 flag técnica
    _resposta_extraida: true
  }
}];

// ============================================
// PROCESSAR EVENTO — Z-API (NORMALIZADO FINAL)
// Critérios:
// - Não duplicar dados
// - Promover o que é importante
// - Corrigir semântica
// - Separar mídia vs foto de perfil
// ============================================

/* ========= HELPERS ========= */

function normalizePhone(raw) {
  if (!raw) return "";
  const p = String(raw).replace(/\D/g, "");
  if (p.length === 11 && !p.startsWith("55")) return "55" + p;
  return p;
}

function toIso(ms) {
  const n = Number(ms);
  return n ? new Date(n).toISOString() : new Date().toISOString();
}

/* ========= INPUT ========= */

const body = typeof $json.body === "object" ? $json.body : {};
const headers = typeof $json.headers === "object" ? $json.headers : {};

/* ========= IDENTIDADE ========= */

const messageId = body.message_id || body.messageId || "";
if (!messageId) return [];

const phone = normalizePhone(body.phone || body.connected_phone || body.connectedPhone || "");
const instanceId = body.instance_id || body.instanceId || "";

/* ========= PROMOÇÃO SEM DUPLICAÇÃO ========= */

// Nome correto do usuário (promovido, não duplicado)
const pushName =
  body.lead_name ||
  body.chatName ||
  body.senderName ||
  body.pushName ||
  "Usuário";

// Conversa (promovida do raw_body)
const conversation_id =
  body.conversation_id ||
  body.chat_lid ||
  null;

/* ========= FLAGS ========= */

const fromMe = Boolean(body.from_me ?? body.fromMe);
const forwarded = Boolean(body.forwarded);
const isGroup = Boolean(body.is_group ?? body.isGroup);

/* ========= BLOQUEIOS ========= */

if (isGroup) {
  return [{ json: { _ignore: true, _reason: "grupo" } }];
}

/* ========= TEXTO ========= */

const texto =
  body.message_text ||
  (body.text && body.text.message) ||
  body.caption ||
  "";

// Mídia detectada antes do bloqueio por texto vazio
const temMidia = !!(body.image || body.video || body.audio || body.voice || body.document);

if (!texto.trim() && !temMidia) {
  return [{ json: { _ignore: true, _reason: "vazio" } }];
}

// Gerar texto descritivo para mídia sem legenda
const textoFinal = texto.trim() || (
  body.image    ? "[Cliente enviou imagem]"    :
  body.video    ? "[Cliente enviou vídeo]"     :
  body.audio || body.voice ? "[Cliente enviou áudio]"    :
  body.document ? "[Cliente enviou documento]" : ""
);

/* ========= MÍDIA (SEM CONFUNDIR PERFIL) ========= */

// Regra:
// - photo / senderPhoto → FOTO DE PERFIL (NÃO É MÍDIA)
// - image / video / audio / document → MÍDIA REAL

let has_media = false;
let media_type = null;
let media_url = "";
let media_source = "none"; // none | user_message

if (body.image) {
  has_media = true;
  media_type = "image";
  media_url = body.image.url || body.image.imageUrl || "";
  media_source = "user_message";
} else if (body.video) {
  has_media = true;
  media_type = "video";
  media_url = body.video.url || body.video.videoUrl || "";
  media_source = "user_message";
} else if (body.audio || body.voice) {
  has_media = true;
  media_type = "audio";
  media_url = body.audio?.url || body.voice || "";
  media_source = "user_message";
} else if (body.document) {
  has_media = true;
  media_type = "document";
  media_url = body.document.url || "";
  media_source = "user_message";
}

/* ========= TEMPO ========= */

const timestamp = toIso(body.data_timestamp || body.momment);
const timestamp_type = "received_at";

/* ========= ORIGEM ========= */

const origin_ip =
  headers["x-forwarded-for"] ||
  headers["x-real-ip"] ||
  "";

/* ========= SEMÂNTICA ========= */

// Correção sem duplicação
const tipo_interacao = fromMe ? "MENSAGEM_AGENTE" : "MENSAGEM_CLIENTE";

/* ========= OUTPUT FINAL ========= */

return [{
  json: {
    // ===== EXISTENTE (INTACTO / CORRIGIDO) =====
    messageId,
    phone,
    pushName,
    texto: textoFinal,

    has_media,
    media_type,
    media_url,
    media_source,

    fromMe,
    forwarded,

    timestamp,
    timestamp_type,

    instanceId,
    origin_ip,

    tipo_interacao,

    conversation_id,

    // ===== FONTE ÚNICA DE VERDADE =====
    raw_body: body
  }
}];

// ============================================
// PROCESSAR MEMÓRIA (BLINDADO PARA PRODUÇÃO)
// Garante último ESTADO VÁLIDO, não última linha
// ============================================

const items = $input.all();

// -----------------------------
// 1. Normalizar e filtrar memória válida
// -----------------------------
const memoria = items
  .map(i => i.json)
  .map(m => ({
    timestamp: new Date(m.timestamp).getTime(),
    mensagem_cliente: String(m.mensagem_cliente || "").trim(),
    resposta_agente: String(m.resposta_agente || "").trim(),
    nome_contato: String(m.nome_contato || "").trim(),

    // estado
    fase_jornada: String(m.fase_jornada || "").trim(),
    dados_pendentes: String(m.dados_pendentes || "").trim(),
    estado_consolidado: String(m.estado_consolidado || "").trim()
  }))
  .filter(m =>
    !isNaN(m.timestamp) &&
    (m.mensagem_cliente || m.resposta_agente)
  );

// -----------------------------
// 2. Ordenar por timestamp (antigo → recente)
// -----------------------------
memoria.sort((a, b) => a.timestamp - b.timestamp);

// -----------------------------
// 3. Últimas 5 mensagens (histórico)
// -----------------------------
const ultimas5 = memoria.slice(-5);

// -----------------------------
// 4. Histórico textual
// -----------------------------
const historico = ultimas5
  .map(m => {
    let bloco = "";
    if (m.mensagem_cliente) bloco += `Cliente: ${m.mensagem_cliente}\n`;
    if (m.resposta_agente) bloco += `Agente: ${m.resposta_agente}\n`;
    return bloco.trim();
  })
  .join("\n\n");

// -----------------------------
// 5. 🔴 BUSCAR ÚLTIMO ESTADO VÁLIDO
// -----------------------------
const ultimoEstadoValido =
  [...ultimas5]
    .reverse()
    .find(m =>
      m.fase_jornada ||
      m.estado_consolidado ||
      m.dados_pendentes
    ) || {};

// -----------------------------
// 6. Output BLINDADO
// -----------------------------
return [{
  json: {
    historico,
    total_memorias_lidas: items.length,
    total_memorias_usadas: ultimas5.length,

    // ✅ estado SEMPRE coerente
    fase_jornada_anterior: ultimoEstadoValido.fase_jornada || "abertura",
    dados_pendentes_anterior: ultimoEstadoValido.dados_pendentes || "",
    estado_consolidado_anterior: ultimoEstadoValido.estado_consolidado || ""
  }
}];

// ============================================
// NODE 2 – CALCULAR ESTADO DA CONVERSA (CORRETO)
// Função: consolidar CONTEXTO + ESTADO ANTERIOR
// NÃO decide estado novo (isso é do LLM)
// ============================================

const items = $input.all();

// Ordem garantida pelo MERGE
const evento  = $input.first().json || {};
const config  = $('Get config').first().json || {};
const memoria = $('PROCESSAR MEMORIA').first().json || {};

// -----------------------------
// 1. Evento atual (imutável)
// -----------------------------
if (!evento || !evento.texto) return [];

// -----------------------------
// 2. Flag de atendimento encerrado
// -----------------------------
const conversa_encerrada =
  memoria.conversa_encerrada === true ||
  memoria.conversa_encerrada === "true";

// -----------------------------
// 3. Estado anterior (SÓ SE NÃO ENCERRADO)
// -----------------------------
const fase_jornada =
  conversa_encerrada ? "" : (memoria.fase_jornada_anterior || "abertura");

const dados_pendentes =
  conversa_encerrada ? "" : (memoria.dados_pendentes_anterior || "");

const estado_consolidado =
  conversa_encerrada ? "" : (memoria.estado_consolidado_anterior || "");

// -----------------------------
// 4. Output CONSOLIDADO
// -----------------------------
return [{
  json: {
    // 🔒 Evento original
    ...evento,

    // 🔒 Config
    _config: {
      agent_name: config.agent_name || "",
      empresa_nome: config.empresa_nome || "",
      instance_id: config.instance_id || "",
      zapi_url: config.zapi_url || "",
      client_token: config.client_token || "",
      system_prompt: config.system_prompt || ""
    },

    // 🧠 Memória (histórico só se não encerrado)
    historico: conversa_encerrada ? "" : (memoria.historico || ""),
    total_memorias_lidas: memoria.total_memorias_lidas || 0,
    total_memorias_usadas: memoria.total_memorias_usadas || 0,

    // 🧭 Estado anterior (bloqueado se encerrado)
    fase_jornada,
    dados_pendentes,
    estado_consolidado,

    // 🚩 Flag explícita para o LLM
    conversa_encerrada,

    // 🕒 Controle
    _estado_timestamp: new Date().toISOString()
  }
}];

// ============================================
// NODE 3 – PREPARAR INPUT GERAL (CORRETO)
// Função: montar INPUT DO LLM
// NÃO altera estado, NÃO decide nada
// ============================================

const item = $json;
if (!item) return [];

// -----------------------------
// 1. Evento atual
// -----------------------------
if (item.fromMe) return [];

const textoAtual = String(item.texto || "").trim();
if (!textoAtual) return [];

// -----------------------------
// 2. Identidade
// -----------------------------
const nomeCliente =
  item.nome_contato ||
  item.pushName ||
  "Cliente";

// -----------------------------
// 3. Flag de encerramento (boolean real)
// -----------------------------
const conversa_encerrada =
  item.conversa_encerrada === true ||
  item.conversa_encerrada === "true";

// -----------------------------
// 4. Contexto condicionado ao estado
// -----------------------------
const historico = conversa_encerrada
  ? "Atendimento anterior encerrado."
  : (item.historico || "Sem histórico recente.");

const fase_jornada = conversa_encerrada ? "" : (item.fase_jornada || "");
const dados_pendentes = conversa_encerrada ? "" : (item.dados_pendentes || "");
const estado_consolidado = conversa_encerrada ? "" : (item.estado_consolidado || "");

// -----------------------------
// 5. INPUT FINAL DO LLM
// -----------------------------
const chatInput = `
Cliente: ${nomeCliente}

ATENDIMENTO ENCERRADO:
${conversa_encerrada ? "sim" : "não"}

ESTADO CONSOLIDADO:
${estado_consolidado}

DADOS PENDENTES:
${dados_pendentes}

FASE DA JORNADA:
${fase_jornada}

HISTÓRICO RECENTE:
${historico}

MENSAGEM ATUAL:
${textoAtual}
`.trim();

// -----------------------------
// 6. OUTPUT
// -----------------------------
return [{
  json: {
    ...item,

    // 🔴 ÚNICO CAMPO LIDO PELO LLM
    chatInput,

    // 🔵 CONTROLE
    sessionId: item.phone,

    _controle: {
      total_memoria_usada: item.total_memorias_usadas || 0
    }
  }
}];

// ============================================
// NODE – DEFINIR PROMPT (CORRETO / PRODUÇÃO)
// Função: preparar payload final para o AI Agent
// NÃO decide estado
// NÃO altera lógica
// ============================================

const data = $json;
if (!data || !data.chatInput) return [];

// -----------------------------
// Texto limpo da mensagem atual
// -----------------------------
const texto =
  typeof data.texto === "string"
    ? data.texto
    : "";

// -----------------------------
// OUTPUT FINAL
// -----------------------------
// ─── ESTADO_NOVO fixo (M-044: protegido, nunca editavel pelo tutor) ───
const ESTADO_NOVO_ATENDIMENTO = `[ESTADO_NOVO]
fase_jornada: abertura | descoberta
dados_ainda_necessarios: [serviço desejado] ou "nenhum"
estado_resumido: [serviço identificado em 1 frase, ex: "Cliente quer impressão colorida A4"]
[/ESTADO_NOVO]`;

// ─── Fallback do texto estatico se config.system_prompt estiver vazio (M-044) ───
// Texto identico ao que sempre esteve hardcoded no AI Agent1, so com o
// trecho de data/hora trocado por marcador (ver injecao abaixo).
const FALLBACK_ATENDIMENTO = `Você é Dizu, assistente virtual da JS Gráfica Rápida, uma gráfica do bairro do Ibura, em Recife (PE). A gráfica foi fundada pelo Sr. Edvam (Didi) junto com Dona Zu e Gabi, e atende a comunidade há mais de uma década com carinho, paciência e eficiência.

