const systemPromptEditavel =
  ((data._config && data._config.system_prompt) || "").trim() || FALLBACK_ATENDIMENTO;

// ─── Data/hora injetada por codigo (M-044, mesmo padrao do connect_event) ───
// Antes essa expressao era avaliada ao vivo pelo n8n dentro do texto fixo
// do AI Agent1. Agora o texto vem do banco (editavel pelo tutor), entao a
// data/hora e injetada aqui por codigo, no mesmo ponto onde antes ficava a
// expressao {{$now...}} original -- mesmo metodo, mesmo fuso, mesmo formato.
const dataHoraAtual = $now.setZone('America/Recife').toFormat('dd/MM/yyyy HH:mm');

const systemPrompt = systemPromptEditavel
  .replace('[[DATA_HORA_ATUAL]]', dataHoraAtual)
  + '\n\n' + ESTADO_NOVO_ATENDIMENTO;

return [{
  json: {
    // identificacao / envio (inalterado)
    chatInput: data.chatInput,
    sessionId: data.sessionId,
    phone: data.phone,
    messageId: data.messageId,
    timestamp: data.timestamp,
    nome_contato: data.nome_contato,
    texto,

    // estado (apenas para log, inalterado)
    fase_jornada: data.fase_jornada || "",
    dados_pendentes: data.dados_pendentes || "",
    estado_consolidado: data.estado_consolidado || "",
    conversa_encerrada: data.conversa_encerrada === true,

    // config
    _config: data._config,

    // prompt final para o AI Agent1 (M-044)
    systemPrompt
  }
}];

const data = $json;
if (!data) return [];

const respostaCompleta = data.output || data.message || '';
const regexEstado = /\[ESTADO_NOVO\]([\s\S]*?)\[\/ESTADO_NOVO\]/;
const match = respostaCompleta.match(regexEstado);

let fase_jornada = data.fase_jornada || '';
let dados_pendentes = data.dados_pendentes || '';
let estado_consolidado = data.estado_consolidado || '';

if (match) {
  const linhas = match[1].split('\n').map(l => l.trim()).filter(Boolean);
  for (const linha of linhas) {
    if (linha.startsWith('fase_jornada:')) fase_jornada = linha.split(':')[1].trim();
    if (linha.startsWith('dados_ainda_necessarios:')) dados_pendentes = linha.split(':')[1].trim();
    if (linha.startsWith('estado_resumido:')) estado_consolidado = linha.split(':')[1].trim();
    if (linha.startsWith('servico_identificado:')) {
      // campo opcional que o LLM pode incluir
    }
  }
}

const mensagemLimpa = respostaCompleta.replace(regexEstado, '').trim();

// Detecta servico a partir do estado_consolidado
let servico_detectado = null;
const estadoLower = estado_consolidado.toLowerCase();
if (estadoLower.includes('impressao') || estadoLower.includes('impressão')) servico_detectado = 'impressao';
else if (estadoLower.includes('xerox') || estadoLower.includes('copia') || estadoLower.includes('cópia')) servico_detectado = 'xerox';
else if (estadoLower.includes('foto')) servico_detectado = 'foto';
else if (estadoLower.includes('plastif')) servico_detectado = 'plastificacao';
else if (estadoLower.includes('encader')) servico_detectado = 'encadernacao';
else if (estadoLower.includes('banner') || estadoLower.includes('adesivo')) servico_detectado = 'banner';
else if (estadoLower.includes('recarga') || estadoLower.includes('vem')) servico_detectado = 'recarga';
else if (estadoLower.includes('consulta') || estadoLower.includes('2ª via') || estadoLower.includes('cpf') || estadoLower.includes('serasa')) servico_detectado = 'consulta';

// Passa para 06-PEDIDOS assim que identifica o servico (fase descoberta ou coleta_dados)
// Nao espera o encerramento — o 06-PEDIDOS faz toda a coleta
const faseQuePassaAoPedido = ['descoberta', 'coleta_dados', 'encerramento'];
const devePassarPedido = servico_detectado !== null && faseQuePassaAoPedido.indexOf(fase_jornada) !== -1;

return [{
  json: {
    ...data,
    message: mensagemLimpa,
    output: mensagemLimpa,
    fase_jornada,
    dados_pendentes,
    estado_consolidado,
    servico_detectado,
    _deve_passar_pedido: devePassarPedido,
    _estado_extraido: true
  }
}];

// ============================================
// PREPARAR LOG MEMÓRIA — SUPABASE (FINAL)
// Espelha 100% a planilha
// Compatível com sunny_memoria_converas
// ============================================

const data = $json;
const agora = new Date();

// -----------------------------
// Timestamp
// -----------------------------
const timestamp =
  data.timestamp
    ? new Date(data.timestamp).toISOString()
    : agora.toISOString();

// -----------------------------
// Identidade (NUNCA NULL)
// -----------------------------
const telefone =
  data.telefone ??
  data.phone ??
  "";

if (!telefone) {
  throw new Error("telefone é obrigatório para salvar memória");
}

const nome_contato =
  data.nome_contato ??
  data.pushName ??
  "Desconhecido";

// -----------------------------
// Mensagens
// -----------------------------
const mensagem_cliente = data.mensagem_cliente ?? data.texto ?? null;
const resposta_agente = data.resposta_agente ?? data.output ?? null;

// -----------------------------
// Classificações
// -----------------------------
const tipo_mensagem = data.tipo_mensagem ?? "atendimento";
const intencao = data.intencao ?? "consulta_geral";
const sentimento = data.sentimento ?? "neutro";
const score_confiança =
  typeof data.score_confiança === "number"
    ? data.score_confiança
    : null;

// -----------------------------
// Jornada / Estado
// -----------------------------
const fase_jornada = data.fase_jornada ?? null;
const dados_pendentes = data.dados_pendentes ?? null;
const estado_consolidado = data.estado_consolidado ?? null;

// -----------------------------
// Canal / Origem
// -----------------------------
const canal = data.canal ?? "whatsapp";
const origem = data.origem ?? "ai_agent";

// -----------------------------
// Contexto
// -----------------------------
const contexto_resumido =
  data.contexto_resumido ??
  "Registro automático de conversa";

// -----------------------------
// Pedido / Comercial
// -----------------------------
const pedido_relacionado = data.pedido_relacionado ?? null;
const fase_do_pedido = data.fase_do_pedido ?? null;

// -----------------------------
// Negócio
// -----------------------------
const tipo_negocio = data.tipo_negocio ?? null;
const segmento = data.segmento ?? null;
const nome_empresa = data.nome_empresa ?? null;
const objetivo_principal = data.objetivo_principal ?? null;
